  '钢铁与工厂的工业强国，信奉火力与装甲。': 'Industriemacht aus Stahl und Fabriken, vertraut auf Feuerkraft und Panzerung.',
  '履带车辆防御 +5%；陆上单位在兵工厂的修理费 −20%。': 'Kettenfahrzeuge erhalten Abwehr +5%; Reparaturkosten von Bodeneinheiten in der Fabrik −20%.',
  '海洋与天空的联邦，重视技术与后勤。': 'Bund von Meer und Himmel, setzt auf Technik und Logistik.',
  '航空单位和舰船视野 +1；航空单位在机场、舰船在港口的修理费 −20%。': 'Lufteinheiten und Schiffe erhalten Sicht +1; Reparaturkosten von Lufteinheiten im Flughafen und Schiffen im Hafen −20%.',
  '山林与雪原的游击之民，擅长地形与隐蔽。': 'Guerillavolk aus Bergwald und Schneeland, nutzt Gelände und Verstecke.',
  '步兵类单位造价 −5%；位于森林、山地的步兵类单位防御 +10%；中型坦克、重型坦克、火箭炮造价 +5%。': 'Fußtruppen erhalten Kosten −5%; Fußtruppen in Wald und Gebirge erhalten Abwehr +10%; Mittelpanzer, Schwerpanzer und Raketenwerfer erhalten Kosten +5%.',
  '商路与黄金的城邦联盟，凭借财力与城墙作战。': 'Städtebund der Handelswege und des Goldes, kämpft mit Geld und Mauern.',
