  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': 'Günstige Einheit, kann Gebäude besetzen und Gebirge und Flüsse betreten.',
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': 'Infanterie mit Panzerfaust, kann Gebäude besetzen, verursacht hohen Schaden an Panzern, Bewegungskosten in Gebirge und Fluss betragen 1.',
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': 'Fernkampf-Infanterie mit Reichweite 2–4, stark gegen Fußtruppen, kann auch leichte Fahrzeuge und Helikopter angreifen. Im Gebirge Reichweite +1. Kann nach dem Bewegen nicht angreifen.',
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': 'Reichweite 1–2, kann nach dem Bewegen noch angreifen. Halbiert beim Angriff die Geländeabwehr des Ziels, stark gegen Fußtruppen in Gebäuden, Wald und Gebirge. Erleidet keinen Konter bei Zielen in 2 Feldern Entfernung. Im Gebirge Reichweite +1. Kann keine Lufteinheiten und Schiffe angreifen, kann nicht besetzen.',
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': 'Reichweite 1, ignoriert beim Angriff die Geländeabwehr des Ziels, stark gegen Fußtruppen in Gebäuden und Gebirge. Entdeckt bei Nebel verborgene Einheiten in Wald und Ruinen auf den 8 umliegenden Feldern. Schwach gegen Ferneinheiten und Fahrzeuge, kann keine Lufteinheiten und Schiffe angreifen, kann nicht besetzen.',
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': 'Unbewaffnet. Deine benachbarten Fußtruppen regenerieren pro Zug 2 HP (kostenlos). Die Wirkung mehrerer Sanitäter addiert sich nicht.',
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': 'Infanterie auf Motorrädern, kann Gebäude besetzen, hat hohe Bewegung und eignet sich zum Besetzen entfernter Gebäude. Kann kein Gebirge betreten.',
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': 'Höchste Bewegung aller Bodeneinheiten, stark gegen Fußtruppen und ungedeckte Geschütze, schwach gegen Panzer.',
  '陆上主力，造价较低，攻击与防御均衡。': 'Rückgrat am Boden, niedrige Kosten, Angriff und Abwehr ausgewogen.',
  '攻击与防御高于轻型坦克，造价适中。': 'Angriff und Abwehr höher als beim Leichtpanzer, mittlere Kosten.',
  '陆上单位中攻击与防御最高，造价高，移动力低。': 'Höchster Angriff und höchste Abwehr aller Bodeneinheiten, hohe Kosten, geringe Bewegung.',
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': 'Reichweite 2–3, kann Schiffe angreifen. Kann nach dem Bewegen nicht angreifen und keine benachbarten feindlichen Einheiten angreifen.',
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': 'Reichweite 3–5, größer als die der Artillerie, stark gegen schwere Fahrzeuge. Kann nach dem Bewegen nicht angreifen.',
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': 'Reichweite 1, stark gegen Lufteinheiten, verursacht auch hohen Schaden an Fußtruppen.',
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Unbewaffnet. Deine benachbarten Fahrzeuge, Lufteinheiten und Schiffe regenerieren pro Zug 1 HP (kostenlos).',
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': 'Bewegt sich unabhängig vom Gelände, stark gegen Bodeneinheiten, schwach gegen Flak.',
  '可攻击陆上单位和直升机，造价低于轰炸机。': 'Kann Bodeneinheiten und Helikopter angreifen, kostet weniger als der Bomber.',
  '对陆上单位和舰船伤害极高，不可攻击航空单位。': 'Verursacht sehr hohen Schaden an Bodeneinheiten und Schiffen, kann keine Lufteinheiten angreifen.',
  '造价低廉的小型舰船，可攻击岸边的陆上单位，擅长攻击登陆艇。': 'Günstiges kleines Schiff, kann Bodeneinheiten an der Küste angreifen, stark gegen Landungsboote.',
  '兼具防空与反潜能力，擅长攻击潜艇和航空单位。': 'Bekämpft Ziele in der Luft und unter Wasser, stark gegen U-Boote und Lufteinheiten.',
  '射程 2–6，可攻击陆上单位和舰船，伤害较高。移动后不可攻击。': 'Reichweite 2–6, kann Bodeneinheiten und Schiffe angreifen, verursacht hohen Schaden. Kann nach dem Bewegen nicht angreifen.',
  '无武装。可搭载 2 个陆上单位，靠岸后卸载。': 'Unbewaffnet. Kann 2 Bodeneinheiten laden und an der Küste entladen.',

