  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。': 'Liefert pro Zug 100 Geld. Deine hier stehenden Bodeneinheiten regenerieren pro Zug 2 HP (kostenpflichtig).',
  '每回合提供 100 资金。可生产陆上单位。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。': 'Liefert pro Zug 100 Geld. Kann Bodeneinheiten produzieren. Deine hier stehenden Bodeneinheiten regenerieren pro Zug 2 HP (kostenpflichtig).',
  '每回合提供 100 资金。可生产航空单位。停留的己方航空单位与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Liefert pro Zug 100 Geld. Kann Lufteinheiten produzieren. Deine hier stehenden Lufteinheiten und Fußtruppen regenerieren pro Zug 2 HP (kostenpflichtig).',
  '每回合提供 100 资金。可生产舰船。停留的己方舰船与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Liefert pro Zug 100 Geld. Kann Schiffe produzieren. Deine hier stehenden Schiffe und Fußtruppen regenerieren pro Zug 2 HP (kostenpflichtig).',
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Deine hier stehenden Fußtruppen regenerieren pro Zug 2 HP (kostenpflichtig). Deine Einheiten im Umkreis von 5 Feldern um deinen Radarturm erhalten Angriff +10%. Die Wirkung mehrerer Radartürme addiert sich nicht.',
  '停留的己方步兵类单位每回合恢复 4 HP，相邻四格内的己方步兵类单位每回合恢复 2 HP（需支付资金）。': 'Deine hier stehenden Fußtruppen regenerieren pro Zug 4 HP, deine Fußtruppen auf den vier Nachbarfeldern pro Zug 2 HP (kostenpflichtig).',
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。位于己方或中立碉堡的单位受到的反击伤害减半，其中远程单位（含投弹手）射程 +1。': 'Deine hier stehenden Fußtruppen regenerieren pro Zug 2 HP (kostenpflichtig). Einheiten in deinem oder einem neutralen Bunker erleiden halben Konterschaden, Ferneinheiten (auch Grenadiere) erhalten dort Reichweite +1.',
  '可占领建筑的兵种（步兵、破甲兵、摩托兵）进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP（最低保留 1 HP）。': 'Truppen, die Gebäude besetzen können (Infanterie, Panzerjäger, Kradschütze), können es betreten und einmal abfeuern: Um ein gewähltes Zielfeld verlieren alle Einheiten im Umkreis von 2 Feldern je 3 HP (mindestens 1 HP bleibt).',

