  '20×12 · 隔海相望，没有陆路，靠登陆艇和飞机': '20×12 · Vom Meer getrennt, kein Landweg, nur Landungsboote und Flugzeuge',
  '22×9 · 三条山间窄路，火炮和狙击手的主场': '22×9 · Drei enge Bergpfade, Heimspiel für Geschütze und Scharfschützen',
  '18×12 · 中央山脊两侧城市、雷达塔、兵工厂扎堆，先抢先赢': '18×12 · Städte, Radartürme und Fabriken dicht am Mittelgrat, wer zuerst kommt, gewinnt',
  '24×14 · 最大的图，南北两路绕湖，海陆空齐全': '24×14 · Größte Karte, zwei Wege um den See im Norden und Süden, Land, See und Luft komplett',
