  '抛射：移动后仍可攻击。': 'Wurf: Kann nach dem Bewegen noch angreifen.',
  '不可攻击相邻的敌方单位，受到相邻敌方单位攻击时也不可反击。': 'Kann keine benachbarten feindlichen Einheiten angreifen und nicht kontern, wenn eine benachbarte feindliche Einheit angreift.',
  '攻击时无视目标的地形防御。': 'Ignoriert beim Angriff die Geländeabwehr des Ziels.',
  '所有阵营均可研究。': 'Für alle Fraktionen erforschbar.',
  '通用与阵营': 'Gemeinsam und Fraktion',
  '克制表　行为攻击方，列为防守方，数值为基础伤害（%）': 'Stärketabelle · Zeilen: Angreifer, Spalten: Verteidiger, Werte: Grundschaden (%)',
  '攻 ＼ 守': 'Angriff \\ Abwehr',
  '胜负': 'Siegregeln',
  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': 'Gilt ein Tageslimit, wird nach dessen Ablauf zuerst die Zahl der Einkommensgebäude jedes Teams verglichen, dann die Gesamtkosten der Einheiten.',
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': 'Jedes Gebäude hat einen Besetzungswert von 20, jedes Besetzen zieht die aktuellen HP der Einheit ab. Eine Einheit mit vollen HP braucht 2 Züge für die Besetzung.',
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': 'Verlässt die besetzende Einheit das Gebäude oder wird sie zerstört, steigt der Besetzungswert wieder auf 20. Verbündete Gebäude können nicht besetzt werden.',
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': 'Die HP beider Einheiten werden addiert, der Teil über 10 wird anteilig zu den Kosten als Geld erstattet.',
  '受到不相邻的敌方单位攻击时不可反击。': 'Gegen nicht benachbarte Angreifer ist kein Konter möglich.',
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Deine Einheiten im Umkreis von 5 Feldern um deinen Radarturm erhalten Angriff +10%. Die Wirkung mehrerer Radartürme addiert sich nicht.',
  '迷雾开启时，己方雷达塔可看见周围 5 格。': 'Bei Nebel sieht dein Radarturm 5 Felder weit.',
  '不提供收入。': 'Liefert kein Einkommen.',
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': 'Truppen, die Gebäude besetzen können, können es betreten und einmal abfeuern: Um ein gewähltes Zielfeld verlieren alle Einheiten im Umkreis von 2 Feldern je 3 HP.',
  '每击毁一个敌方单位，星级 +1，最高 3 星。': 'Jede zerstörte feindliche Einheit gibt Sterne +1, höchstens 3★.',
  '每 1 星攻击 +5%、防御 +5%。': 'Je 1★ Angriff +5% und Abwehr +5%.',
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': 'Wähle nach dem Bewegen der Transporteinheit „Entladen“ und setze die geladene Einheit auf ein benachbartes, betretbares freies Feld. Entladene Einheiten können in diesem Zug nicht mehr handeln.',
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': 'Ist die Kraftleiste voll, kannst du die Spezialkraft in deinem Zug einsetzen; sie wirkt bis zum Beginn deines nächsten Zuges.',
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': 'Spezialkräfte wirken nur auf die eigene Fraktion. Die Spezialkräfte der Kommandanten stehen auf der Seite „Kommandant“.',
  '特长与阵营特性': 'Talent und Fraktionsmerkmal',
  '每位指挥官拥有一项特长，开局即生效。': 'Jeder Kommandant hat ein Talent, das ab Spielbeginn wirkt.',
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': 'Ein Kommandant hat außerdem das Merkmal seiner Fraktion, unabhängig von der Armeefarbe in dieser Partie.',
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': 'Quellen für Forschungspunkte: Forschungsbudget, eigene Labore und die Forschungsweise jeder Fraktion (siehe Seite „Fraktionen“).',
  '多阵营与结盟': 'Mehrparteien und Bündnisse',
  '同队阵营不可互相攻击，不可占领友方的建筑。可穿过友方单位所在的格子，但不可停留。': 'Fraktionen eines Teams können einander nicht angreifen und keine verbündeten Gebäude besetzen. Felder mit verbündeten Einheiten lassen sich durchqueren, aber nicht als Halt nutzen.',
  '迷雾开启时，同队阵营共享视野。': 'Bei Nebel teilen Fraktionen eines Teams ihre Sicht.',
  '推进战役后解锁。': 'Wird im Lauf der Kampagne freigeschaltet.',
