  '开局时决定': 'Wird zu Spielbeginn bestimmt',
  '仅可看见己方单位和建筑周围的格子。森林、礁石、废墟中的敌方单位仅在相邻时可被发现，视野范围再大也看不到。': 'Du siehst nur die Felder um deine Einheiten und Gebäude. Feindliche Einheiten im Wald, auf Riffen und in Ruinen werden nur von benachbarten Feldern aus entdeckt, egal wie weit die Sicht reicht.',
  '开局时各阵营持有的资金。': 'Geld jeder Fraktion zu Spielbeginn.',
  '到达天数上限时，按建筑数和单位总造价判定胜负。选择“无”则不设上限。': 'Ist das Tageslimit erreicht, entscheiden Gebäudezahl und Gesamtkosten der Einheiten. Bei „Keine“ gibt es kein Limit.',
  '攻击和受到攻击均可积累技能槽，积满后可发动指挥官技能。': 'Angreifen und angegriffen werden füllt die Kraftleiste; ist sie voll, lässt sich die Spezialkraft einsetzen.',
  '指挥官的特长与阵营特性。关闭后各阵营的数值相同。': 'Talente der Kommandanten und Fraktionsmerkmale. Ausgeschaltet haben alle Fraktionen gleiche Werte.',
  '支付研究经费获得研究点，解锁通用、阵营、指挥官三类科技。': 'Forschungsbudget zahlen, Forschungspunkte erhalten und drei Arten Technik freischalten: gemeinsame, Fraktions- und Kommandantentechnik.',
  '阵营数较少的队伍开局资金增加，每回合收入也略有增加。': 'Teams mit weniger Fraktionen erhalten mehr Startgeld und etwas mehr Einkommen pro Zug.',
  '三支及以上队伍对战时，击毁敌方单位可获得其造价的一部分资金。': 'Kämpfen drei oder mehr Teams, bringt jede zerstörte feindliche Einheit einen Teil ihrer Kosten als Geld.',
  '已恢复推荐设置': 'Empfehlung geladen',
  '开始演示': 'Demo starten',
  '开始观战': 'Zuschauen',
  '也可以点右上角的喇叭图标开关。': 'Auch über das Lautsprechersymbol oben rechts umschaltbar.',
  '背景音乐的音量，不影响音效。': 'Lautstärke der Hintergrundmusik, ohne Einfluss auf die Soundeffekte.',
  '移动、攻击等动画的播放速度。': 'Tempo der Animationen für Bewegung, Angriff und mehr.',
  '电脑加速': 'KI beschleunigen',
  '电脑回合以 4 倍速播放。': 'KI-Züge laufen mit 4-fachem Tempo.',
  '镜头跟随电脑': 'Kamera folgt KI',
  '电脑行动时，镜头自动跟随。': 'Die Kamera folgt den Aktionen der KI automatisch.',
  '在地图上显示格线。': 'Zeigt das Raster auf der Karte.',
  '转场动画': 'Übergänge',
  '开战、回合切换、胜负时的阵营色横条和大字。关闭后回合切换改为普通横幅。': 'Balken in Fraktionsfarbe und große Schrift bei Kampfbeginn, Zugwechsel und Spielende. Ausgeschaltet zeigt der Zugwechsel ein schlichtes Banner.',
  '常显按键提示': 'Tastenhinweise immer',
  '关：仅在菜单、选择目标等场合显示按键提示。开：对局中始终显示。': 'Aus: Tastenhinweise erscheinen nur in Menüs, bei der Zielwahl und Ähnlichem. An: Sie bleiben in der Partie immer sichtbar.',
  '每格的显示大小。选择“自动”时，一屏约显示 15×10 格。': 'Anzeigegröße eines Felds. Bei „Auto“ zeigt der Bildschirm etwa 15×10 Felder.',
