  // ── 通用科技风味 ──
  '口径统一之后，前线再也没领错过炮弹。': 'Seit das Kaliber einheitlich ist, bekommt die Front nie mehr die falschen Granaten.',
  '多夹一层，多活一回。': 'Eine Schicht mehr, ein Leben mehr.',
  '一个人打不过，就三个人一起打。': 'Wer allein nicht gewinnt, kommt zu dritt.',
  '扳手比子弹便宜。': 'Schraubenschlüssel sind billiger als Kugeln.',
  '零件先做好，到了再拼。': 'Teile vorher fertigen, vor Ort zusammenstecken.',
  '路修到哪，兵就到哪。': 'Wo eine Straße hinführt, sind bald Truppen.',
  '先看清楚，再迈腿。': 'Erst hinsehen, dann losgehen.',
  '命令到得快，机会才抓得住。': 'Nur ein schneller Befehl erwischt die Gelegenheit.',
  '他们的电报，我们比他们的将军先看到。': 'Ihre Telegramme lesen wir früher als ihre Generäle.',

  // ── 阵营科技风味 ──
  '一个人只拧一颗螺丝，拧一万遍。': 'Jeder dreht nur eine Schraube. Zehntausendmal.',
  '烧红，浸冷，再烧红。': 'Glühen, abschrecken, wieder glühen.',
  '第一百四十一座高炉点火那天，炉城放了半天假。': 'Als der hunderteinundvierzigste Hochofen angeblasen wurde, bekam Ofenstadt einen halben Tag frei.',
  '上次打偏的那一发，已经算进去了。': 'Der Schuss, der letztes Mal danebenging, ist schon eingerechnet.',
  '墙厚不厚，要看拿什么敲。': 'Ob eine Mauer dick ist, hängt davon ab, womit man anklopft.',
  '不用瞄，那一片都是。': 'Zielen unnötig, es ist die ganze Gegend.',
  '领航员家的孩子，先会看潮，后会走路。': 'Lotsenkinder lernen erst die Gezeiten lesen, dann laufen.',
  '十二座港，终于用上了同一种螺栓。': 'Zwölf Häfen, endlich derselbe Bolzen.',
  '各港的船头一次朝着同一个方向。': 'Zum ersten Mal zeigen die Buge aller Häfen in dieselbe Richtung.',
  '起飞之前，先问问风。': 'Vor dem Start erst den Wind fragen.',
  '油管对上的那一下，两个飞行员都不敢喘气。': 'Wenn der Schlauch einrastet, wagt keiner der beiden Piloten zu atmen.',
  '船是飞机的眼睛，飞机是船的拳头。': 'Das Schiff ist das Auge des Flugzeugs, das Flugzeug die Faust des Schiffs.',
  '树皮上三道刻痕，意思是往左。': 'Drei Kerben in der Rinde heißen: nach links.',
  '你看见一棵树。树也看见了你。': 'Du siehst einen Baum. Der Baum sieht dich auch.',
  '寨里最好的猎户，一年只下山一次。': 'Der beste Jäger des Dorfs kommt nur einmal im Jahr vom Berg.',
  '你家的田我帮着收，我家的仗你帮着打。': 'Ich helfe bei deiner Ernte, du hilfst bei meinem Krieg.',
  '嚼碎了敷上，明天还能走。': 'Zerkauen, auflegen, morgen läuft er wieder.',
  '木牌上写着：这一季，每户出一个人。': 'Auf der Holztafel steht: Diese Saison stellt jeder Hof einen Mann.',
  '进城收一道，出城再收一道。': 'Einmal kassieren beim Hineingehen, einmal beim Hinausgehen.',
  '沙原上没有路，驼队走过的地方就是路。': 'In der Sandebene gibt es keine Wege. Der Weg ist dort, wo die Karawane ging.',
  '这座矿，从今天起只卖给我们。': 'Diese Mine verkauft ab heute nur noch an uns.',
  '多砌一层，少赔一座城。': 'Eine Lage Steine mehr, eine verlorene Stadt weniger.',
  '老兵贵一点，但不用教。': 'Veteranen sind teurer, aber fertig ausgebildet.',
  '城墙上的炮不用发饷。': 'Kanonen auf der Mauer verlangen keinen Sold.',
  '灯不用太亮，够看见下一步就行。': 'Die Lampe muss nicht hell sein. Für den nächsten Schritt reicht sie.',
  '三十年前挖的坑道，图纸只有他们还留着。': 'Die Stollen wurden vor dreißig Jahren gegraben. Die Pläne haben nur noch sie.',
  '铁轨铺到哪里，潮就涨到哪里。': 'Wo die Gleise liegen, dorthin steigt die Flut.',

  // ── 阵营科技名 ──
  '矿灯': 'Grubenlampe',
  '旧坑道': 'Alte Stollen',
  '黑潮': 'Schwarze Flut',

