  '全军视野 +1。': 'Alle deine Einheiten erhalten Sicht +1.',
  '位于荒地、废墟、沙滩的己方单位防御再 +10%。': 'Deine Einheiten in Ödland, Ruinen und am Strand erhalten zusätzlich Abwehr +10%.',
