  '{fort}上的远程单位射程 +1，两者不叠加。': 'Reichweite +1 für Ferneinheiten auf dem Feld „{fort}“; beides addiert sich nicht.',
  '{mountain}上的步兵类远程单位射程 +1，两者不叠加。': 'Reichweite +1 für Ferneinheiten der Fußtruppen auf dem Feld „{mountain}“; beides addiert sich nicht.',
  '车辆在{land}修理，航空单位在{airport}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Reparatur von Fahrzeugen: {land}; von Lufteinheiten: {airport}; von Schiffen: {port}. Fußtruppen können in jedem deiner Gebäude repariert werden.',
  '车辆在{land}修理，航空单位在{airport}修理。步兵类单位可在任意己方建筑修理。': 'Reparatur von Fahrzeugen: {land}; von Lufteinheiten: {airport}. Fußtruppen können in jedem deiner Gebäude repariert werden.',
  '车辆在{land}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': 'Reparatur von Fahrzeugen: {land}; von Schiffen: {port}. Fußtruppen können in jedem deiner Gebäude repariert werden.',
  '车辆在{land}修理。步兵类单位可在任意己方建筑修理。': 'Reparatur von Fahrzeugen: {land}. Fußtruppen können in jedem deiner Gebäude repariert werden.',
  '与{name}相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Neben {name}: Deine Fahrzeuge, Lufteinheiten und Schiffe regenerieren pro Zug 1 HP (kostenlos).',
  '与{name}相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名{name}的效果不叠加。': 'Neben {name}: Deine Fußtruppen regenerieren pro Zug 2 HP (kostenlos). Die Wirkung mehrerer Einheiten vom Typ {name} addiert sich nicht.',
