  '击毁敌方的强化单位时，获得它强化价的一半（向上取整）。运输单位搭载的强化单位各自计算。': 'Zerstörst du eine verstärkte feindliche Einheit, erhältst du die Hälfte ihrer Verstärkungskosten (aufgerundet). Verstärkte Einheiten in einer Transporteinheit werden jeweils einzeln berechnet.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': 'Fußtruppen erhalten Sicht +3 ({mountain}). Deine Gebäude sehen ihr eigenes Feld, {hq} sieht 2 Felder weit, {tower} sieht 5 Felder weit.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格。': 'Fußtruppen erhalten Sicht +3 ({mountain}). Deine Gebäude sehen ihr eigenes Feld, {hq} sieht 2 Felder weit.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{tower}可看见周围 5 格。': 'Fußtruppen erhalten Sicht +3 ({mountain}). Deine Gebäude sehen ihr eigenes Feld, {tower} sieht 5 Felder weit.',
