  '完整：每次占领弹出小窗，演出步兵占领建筑的过程；占领司令部时为整屏演出。简短：只在地图上显示跳减的占领值和换色。开启“电脑加速”时，电脑回合自动使用简短演出。': 'Voll: Bei jeder Besetzung öffnet sich ein kleines Fenster und zeigt, wie Infanterie das Gebäude besetzt; die Besetzung eines HQ wird bildschirmfüllend gezeigt. Kurz: Auf der Karte erscheinen nur der sinkende Besetzungswert und der Farbwechsel. Ist „KI beschleunigen“ aktiv, nutzen KI-Züge automatisch die kurze Szene.',
