  '很久以前，一颗陨星砸进了中央海的正中。': 'Vor langer Zeit schlug ein Meteor mitten ins Zentralmeer.',
  '砸出来的大坑叫海眼。海水从这里进，也从这里出。': 'Die Grube, die er schlug, heißt Meeresauge. Hier strömt das Wasser hinein, hier strömt es hinaus.',
  '每过三十年，海水从海眼退下去一次。': 'Alle dreißig Jahre zieht sich das Meer durch das Meeresauge zurück.',
  '海床露出来，上面是成片的陨星碎片。': 'Der Meeresgrund liegt frei, übersät mit Meteorsplittern.',
  '谁挖得多，往后三十年谁说了算。': 'Wer am meisten fördert, hat dreißig Jahre das Sagen.',
  '所以每退一次潮，四国就打一次仗。': 'Darum führen die vier Länder bei jeder Ebbe Krieg.',
  '今年又退潮了。': 'Dieses Jahr ist wieder Ebbe.',
  '这一次，海眼里开出来一支黑色的军队。': 'Und diesmal kommt aus dem Meeresauge eine schwarze Armee.',
  '赤焰的新人燕烽，头一回带兵。': 'Yan Feng, die Neue der Purpurflamme, führt zum ersten Mal Truppen.',
  '到了再说！': 'Erst mal ankommen!',
  '晨曦镇外，今年第一座陨星矿露了头。': 'Vor Morgenlicht liegt die erste Meteormine dieses Jahres frei.',
  '燕烽只有一个念头：第一个到。': 'Yan Feng hat nur einen Gedanken: als Erste da sein.',
  '最大的一片矿在海床正中，海眼的边上。': 'Das größte Erzfeld liegt mitten auf dem Meeresgrund, am Rand des Meeresauges.',
  '炉城的命令很简单：赶到那里，占住它。': 'Der Befehl aus Ofenstadt ist einfach: hin und besetzen.',
  '去海眼要走水路，船在苍蓝手里。': 'Zum Meeresauge führt nur der Seeweg, und die Schiffe hat Tiefazur.',
  '一支没有旗的黑色舰队，开进了内海。': 'Eine schwarze Flotte ohne Flagge ist ins Binnenmeer eingelaufen.',
  '翠林的寨子正被人一座一座地烧。': 'Im Jadewald brennt ein Dorf nach dem anderen.',
  '放火的人，打着赤焰的旗。': 'Die Brandstifter tragen die Flagge der Purpurflamme.',
