  '隐形的航空单位：敌方只有相邻时才能发现（迷雾关闭时也有效）。对航空单位伤害高，对陆上单位伤害中等。': 'Getarnte Lufteinheit: Der Feind entdeckt sie nur von einem benachbarten Feld aus (auch ohne Nebel). Hoher Schaden an Lufteinheiten, mittlerer Schaden an Bodeneinheiten.',
  '射程 2–5 的舰船，移动后不可攻击。上一个己方回合没有攻击时处于下潜状态：敌方只有相邻时才能发现（迷雾关闭时也有效）。': 'Schiff mit Reichweite 2–5. Kann nach dem Bewegen nicht angreifen. Hat es in deinem letzten Zug nicht angegriffen, ist es getaucht: Der Feind entdeckt es nur von einem benachbarten Feld aus (auch ohne Nebel).',
  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': 'Bodeneinheiten, die ihre Bewegung auf diesem Feld beenden, sammeln ihn auf und erhalten 1–3 Meteorsplitter (für jeden Haufen zu Spielbeginn zufällig festgelegt); das Feld wird zur Splittergrube (wie Ödland). Die Bewegungskosten für Radfahrzeuge betragen 3.',
  '迷雾开启时，森林中的单位只有相邻时才会被发现。': 'Bei Nebel werden Einheiten im Wald nur von benachbarten Feldern aus entdeckt.',
  '只有步兵类单位可以进入。狙击手、投弹手在山地上射程 +1。迷雾开启时，步兵类单位在山地上视野 +3。': 'Nur Fußtruppen können es betreten. Scharfschütze und Grenadier erhalten im Gebirge Reichweite +1. Bei Nebel erhalten Fußtruppen im Gebirge Sicht +3.',
