  '全军立即恢复 2 HP。己方下回合开始前：全军防御 +20%。': 'Alle deine Einheiten regenerieren sofort 2 HP. Bis zum Beginn deines nächsten Zuges: Alle deine Einheiten erhalten Abwehr +20%.',
  '立即获得「己方建筑数 × 80」的资金，再加回合收入的 20%。': 'Du erhältst sofort „Anzahl deiner Gebäude × 80“ Geld, dazu 20% des Zugeinkommens.',
